INSERT INTO workouts (id, title, level, equipment, focus, minutes, image, is_new, is_hybrid, description) VALUES
(1, 'Latihan Hybrid Pembangun Kekuatan untuk Lomba', 'Lanjut', 'Peralatan Lengkap', 'Kekuatan', 45, 'assets/images/barbell_deadlift.jpg', 1, 1, 'Kombinasi latihan kekuatan dan kondisi fisik yang dirancang untuk mempersiapkan tubuh Anda menghadapi lomba hybrid. Mulai dengan mobilitas, lanjut ke gerakan beban utama, dan tutup dengan penahanan inti serta pendinginan.'),
(2, 'Inti Sirkuit Balap Hibrid 20 Menit', 'Lanjut', 'Peralatan Lengkap', 'Kekuatan', 20, 'assets/images/hybrid_floor_workout.jpg', 0, 1, 'Sirkuit singkat dan padat untuk membangun daya tahan dan kekuatan inti. Gerakan berbasis waktu menjaga detak jantung Anda tetap tinggi.'),
(3, 'Latihan Hybrid Kekuatan & Pembentukan 30 Menit', 'Lanjut', 'Peralatan Lengkap', 'Kekuatan', 30, 'assets/images/dumbbell_squat.jpg', 0, 1, 'Latihan seluruh tubuh dengan beban untuk membentuk otot sekaligus meningkatkan kekuatan. Fokus pada teknik yang rapi di setiap repetisi.'),
(4, 'HIIT Pembakar Lemak 25 Menit', 'Menengah', 'Tanpa Peralatan', 'HIIT', 25, 'assets/images/hiit_red_training.jpg', 0, 0, 'Interval intensitas tinggi tanpa peralatan untuk membakar kalori dan meningkatkan kebugaran jantung.'),
(5, 'Yoga Pemulihan Seluruh Tubuh', 'Pemula', 'Matras', 'Yoga', 30, 'assets/images/plank_pose.jpg', 0, 0, 'Alur yoga lembut untuk melepas ketegangan otot dan membantu pemulihan setelah hari yang aktif.'),
(6, 'Pilates Inti dan Postur 20 Menit', 'Pemula', 'Matras', 'Pilates', 20, 'assets/images/core_plank.jpg', 0, 0, 'Latihan Pilates di matras untuk menguatkan otot inti dan memperbaiki postur tubuh.'),
(7, 'Dasar Latihan Beban untuk Gym', 'Pemula', 'Peralatan Lengkap', 'Kekuatan', 40, 'assets/images/metcon_barbell.jpg', 0, 0, 'Pengenalan gerakan dasar dengan barbel dan mesin agar Anda percaya diri saat memulai latihan di gym.'),
(8, 'Sirkuit HIIT Dumbel 15 Menit', 'Menengah', 'Dumbel', 'HIIT', 15, 'assets/images/kettlebell_squat.jpg', 0, 0, 'Sirkuit cepat dengan dumbel yang memadukan gerakan kekuatan dan kardio dalam waktu singkat.'),
(9, 'Yoga Alur Pagi 20 Menit', 'Pemula', 'Matras', 'Yoga', 20, 'assets/images/group_workout.jpg', 0, 0, 'Alur yoga singkat untuk membangunkan tubuh dan menenangkan pikiran sebelum memulai hari.'),
(10, 'Yoga Peregangan Pinggul 25 Menit', 'Menengah', 'Matras', 'Yoga', 25, 'assets/images/running_lunge.jpg', 0, 0, 'Rangkaian peregangan untuk melepas kekakuan di pinggul dan punggung bawah.'),
(11, 'Pilates Seluruh Tubuh 30 Menit', 'Menengah', 'Matras', 'Pilates', 30, 'assets/images/strength_dumbbell_row.webp', 0, 0, 'Latihan Pilates menyeluruh yang melatih kontrol, keseimbangan, dan kekuatan inti.'),
(12, 'Pilates Kaki dan Bokong 20 Menit', 'Pemula', 'Matras', 'Pilates', 20, 'assets/images/group_running.jpg', 0, 0, 'Fokus pada penguatan kaki dan bokong dengan gerakan terkendali yang ramah sendi.');
